from src.sliding_window import max_subarray_sum, longest_unique_substr, min_subarray_length


def test_max_subarray_sum():
    assert max_subarray_sum([1, 3, -1, -3, 5, 3, 6], 3) == 14
    assert max_subarray_sum([1, 2, 3], 2) == 5


def test_longest_unique_substr():
    assert longest_unique_substr("abcabcbb") == 3
    assert longest_unique_substr("bbbbb") == 1
    assert longest_unique_substr("") == 0


def test_min_subarray_length():
    assert min_subarray_length([2, 3, 1, 2, 4, 3], 7) == 2
    assert min_subarray_length([1, 1, 1, 1], 10) == 0


def test_max_subarray_sum_single_window():
    assert max_subarray_sum([5], 1) == 5


def test_longest_unique_substr_all_unique():
    assert longest_unique_substr("abcde") == 5
